const NOMBRES = { temperatura: 'Temperatura', humedad: 'Humedad', presion: 'Presión', calidad_aire: 'Calidad del aire' };
const UNIDADES = { temperatura: ' °C', humedad: ' %', presion: ' hPa', calidad_aire: ' Rs/R0' };
const valores = { temperatura: l.temperatura, humedad: l.humedad, presion: l.presion, calidad_aire: msg.calculado.rsR0 };
const crudos = { temperatura: l.temperatura, humedad: l.humedad, presion: l.presion, calidad_aire: l.mq135_v };
const contadores = flow.get('contadoresAlertas') ?? {};
const acciones = [];
const COLUMNAS = 'id, dispositivo_id, ubicacion_id, tipo, variable, mensaje, peor_valor, abierta_en, cerrada_en';
const accion = (nombre, variable, query, params) => ({
    accion: nombre,
    aviso: { nodo, unidad: UNIDADES[variable] },
    query: `${query} RETURNING ${COLUMNAS}`,
    params,
});
const abrir = (tipo, variable, mensaje, valor) =>
    accion('abierta', variable, `INSERT INTO alertas (dispositivo_id, ubicacion_id, tipo, variable, mensaje, valor_inicio, peor_valor)
VALUES ($1, $2, $3, $4, $5, $6, $6)
ON CONFLICT DO NOTHING`, [dispositivoId, ubicacionId, tipo, variable, mensaje, valor]);
const cerrar = (alerta, motivo) =>
    accion('cerrada', alerta.variable, 'UPDATE alertas SET cerrada_en = now(), motivo_cierre = $2 WHERE id = $1 AND cerrada_en IS NULL',
        [alerta.id, motivo]);
const empeorar = (alerta, valor) =>
    accion('actualizada', alerta.variable, 'UPDATE alertas SET peor_valor = $2 WHERE id = $1 AND cerrada_en IS NULL',
        [alerta.id, valor]);
const buscar = (tipo, variable) => abiertas.find((x) => x.tipo === tipo && x.variable === variable);
const distancia = (valor, u) =>
    Math.max(u.min === null ? 0 : u.min - valor, u.max === null ? 0 : valor - u.max, 0);
const numero = (valor) => String(Number(valor));
for (const variable of Object.keys(NOMBRES)) {
    const clave = `${dispositivoId}:${variable}`;
    const c = (contadores[clave] ??= { fuera: 0, dentro: 0, nulos: 0 });
    const umbral = umbrales.find((u) => u.variable === variable);
    const alerta = buscar('UMBRAL', variable);
    const valor = valores[variable];
    if (!umbral) {
        c.fuera = 0;
        c.dentro = 0;
        if (alerta) acciones.push(cerrar(alerta, 'umbral desactivado'));
    } else if (valor !== null) {
        const bajo = umbral.min !== null && valor < umbral.min;
        const alto = umbral.max !== null && valor > umbral.max;
        if (bajo || alto) {
            c.fuera += 1;
            c.dentro = 0;
            if (alerta) {
                if (distancia(valor, umbral) > distancia(Number(alerta.peor), umbral)) acciones.push(empeorar(alerta, valor));
            } else if (c.fuera >= 2) {
                const mensaje = variable === 'calidad_aire' && bajo
                    ? `Calidad del aire en nivel ${msg.calculado.nivel}`
                    : bajo
                        ? `${NOMBRES[variable]} bajo el mínimo (${numero(umbral.min)}${UNIDADES[variable]})`
                        : `${NOMBRES[variable]} sobre el máximo (${numero(umbral.max)}${UNIDADES[variable]})`;
                acciones.push(abrir('UMBRAL', variable, mensaje, valor));
            }
        } else {
            c.dentro += 1;
            c.fuera = 0;
            if (alerta && c.dentro >= 2) acciones.push(cerrar(alerta, 'volvió al rango'));
        }
    }
    const sensor = buscar('SENSOR', variable);
    if (crudos[variable] === null) {
        const precalentando = variable === 'calidad_aire' && l.uptime !== null && l.uptime < 180;
        if (!precalentando) {
            c.nulos += 1;
            if (!sensor && c.nulos >= 3) acciones.push(abrir('SENSOR', variable, `${NOMBRES[variable]} sin respuesta`, null));
        }
    } else {
        c.nulos = 0;
        if (sensor) acciones.push(cerrar(sensor, 'el sensor volvió a responder'));
    }
}
flow.set('contadoresAlertas', contadores);
return [acciones];

const f = msg.payload[0];
if (!f) return null;
msg.payload = {
    tipo: 'alerta',
    accion: msg.accion,
    ubicacionId: f.ubicacion_id,
    alerta: {
        id: Number(f.id),
        ubicacionId: f.ubicacion_id,
        dispositivoId: f.dispositivo_id,
        nodo: msg.aviso.nodo,
        tipo: f.tipo,
        variable: f.variable,
        mensaje: f.mensaje,
        abiertaEn: new Date(f.abierta_en).toISOString(),
        cerradaEn: f.cerrada_en === null ? null : new Date(f.cerrada_en).toISOString(),
        peorValor: f.peor_valor === null ? null : `${Number(f.peor_valor)}${msg.aviso.unidad}`,
    },
};
delete msg.query;
delete msg.params;
delete msg.pgsql;
return msg;
